// Recurring share of revenue (v258). A sale is recurring when its invoice was generated by a recurring schedule (a retainer or repeat billing); everything
// else is one-off. The share is recurring revenue over total revenue for the period, before tax. Pure.

export interface ShareSale { date: string; qty: number; unitPrice: number; invoiceId?: string }
export interface ShareRun { invoiceId: string }

export function recurringShare(sales: ShareSale[], runs: ShareRun[], period: { from: string; to: string }) {
  const recurringIds = new Set(runs.map((r) => r.invoiceId));
  let recurring = 0, total = 0;
  for (const s of sales) {
    const m = s.date.slice(0, 7);
    if (m < period.from || m > period.to) continue;
    const value = s.qty * s.unitPrice;
    total += value;
    if (s.invoiceId && recurringIds.has(s.invoiceId)) recurring += value;
  }
  total = Math.round(total * 100) / 100;
  recurring = Math.round(recurring * 100) / 100;
  return { recurring, oneOff: Math.round((total - recurring) * 100) / 100, total, recurringPct: total > 0 ? Math.round((recurring / total) * 1000) / 10 : null };
}

export function recurringStatus(pct: number | null, targetPct: number | undefined): "not_set" | "no_revenue" | "on_target" | "below_target" {
  if (targetPct === undefined) return "not_set";
  if (pct === null) return "no_revenue";
  return pct >= targetPct ? "on_target" : "below_target";
}
